│  │  ├─ product/     # ProductCard, ProductGallery
│  │  └─ cart/        # CartItem, CartSummary
│  ├─ pages/
│  │  ├─ api/         # API routes (auth, checkout)
│  │  ├─ _app.tsx
│  │  ├─ index.tsx
│  │  ├─ product/[slug].tsx
│  │  ├─ cart.tsx
