## 5. Core Components & Pages

### 5.1 Layout

```tsx
// src/components/layout/Header.tsx
import { Flex, Box, Link, Button } from "@chakra-ui/react";
import { useSelector } from "react-redux";
import { RootState } from "../../store/store";

export const Header = () => {
  const cartCount = useSelector((state: RootState) => state.cart.items.length);

  return (
    <Flex as="header" bg="gray.800" color="white" p={4} align="center">
      <Box flex="1">
        <Link href="/">MyShop</Link>
      </Box>
      <Box>
        <Link href="/cart" mr={4}>
          Cart ({cartCount})
        </Link>
        <Button variant="outline">Login</Button>
      </Box>
    </Flex>
  );
};
```

### 5.2 Product Card

```tsx
// src/components/product/ProductCard.tsx
import { Box, Image, Text, Button } from "@chakra-ui/react";
import { Product } from "../../types";

interface Props {
  product: Product;
}

export const ProductCard = ({ product }: Props) => {
  return (
    <Box borderWidth="1px" borderRadius="lg" overflow="hidden" p={4}>
      <Image src={product.imageUrl} alt={product.title} />
      <Text mt={2} fontWeight="bold">{product.title}</Text>
      <Text>${product.price.toFixed(2)}</Text>
      <Button mt={2} colorScheme="teal" size="sm">
        Add to Cart
      </Button>
    </Box>
  );
};
```

### 5.3 Product Page (SSR)

```tsx
// src/pages/product/[slug].tsx
import { GetServerSideProps } from "next";
import { Product } from "../../types";
import { ProductCard } from "../../components/product/ProductCard";

export const getServerSideProps: GetServerSideProps = async ({ params }) => {
  const res = await fetch(`https://api.myshop.com/products/${params?.slug}`);
  const product: Product = await res.json();

  return { props: { product } };
};

export default function ProductPage({ product }: { product: Product }) {
  return <ProductCard product={product} />;
}
```

### 5.4 Cart Page

```tsx
// src/pages/cart.tsx
import { useSelector, useDispatch } from "react-redux";
import { RootState } from "../store/store";
import { removeFromCart } from "../store/slices/cartSlice";
import { Box, Text, Button } from "@chakra-ui/react";

export default function Cart() {
  const items = useSelector((state: RootState) => state.cart.items);
  const dispatch = useDispatch();

  const total = items.reduce((sum, item) => sum + item.price * item.qty, 0);

  return (
    <Box p={4}>
      <Text fontSize="2xl" mb={4}>Shopping Cart</Text>
      {items.map(item => (
        <Box key={item.id} display="flex" justifyContent="space-between" mb={2}>
          <Text>{item.title} x{item.qty}</Text>
          <Text>${(item.price * item.qty).toFixed(2)}</Text>
          <Button size="sm" onClick={() => dispatch(removeFromCart(item.id))}>Remove</Button>
        </Box>
      ))}
      <Text mt={4} fontWeight="bold">Total: ${total.toFixed(2)}</Text>
      <Button mt={2} colorScheme="teal">Proceed to Checkout</Button>
    </Box>
  );
}
```

