## 6. State Management (Redux Toolkit)

```ts
// src/store/slices/cartSlice.ts
import { createSlice, PayloadAction } from "@reduxjs/toolkit";
import { Product } from "../../types";

interface CartState {
  items: Array<Product & { qty: number }>;
}

const initialState: CartState = { items: [] };

export const cartSlice = createSlice({
  name: "cart",
  initialState,
  reducers: {
    addToCart(state, action: PayloadAction<Product>) {
      const existing = state.items.find(i => i.id === action.payload.id);
      if (existing) {
        existing.qty += 1;
      } else {
        state.items.push({ ...action.payload, qty: 1 });
      }
    },
    removeFromCart(state, action: PayloadAction<string>) {
      state.items = state.items.filter(i => i.id !== action.payload);
    },
    clearCart(state) {
      state.items = [];
    },
  },
});

export const { addToCart, removeFromCart, clearCart } = cartSlice.actions;
export default cartSlice.reducer;
```

```ts
// src/store/store.ts
import { configureStore } from "@reduxjs/toolkit";
import cartReducer from "./slices/cartSlice";
import productReducer from "./slices/productSlice";
import userReducer from "./slices/userSlice";

export const store = configureStore({
  reducer: {
    cart: cartReducer,
    product: productReducer,
    user: userReducer,
  },
});

export type RootState = ReturnType<typeof store.getState>;
export type AppDispatch = typeof store.dispatch;
```

---

## 7. API Integration

### 7.1 RTK Query Setup

```ts
// src/store/apiSlice.ts
import { createApi, fetchBaseQuery } from "@reduxjs/toolkit/query/react";
import { Product } from "../types";

export const apiSlice = createApi({
  reducerPath: "api",
  baseQuery: fetchBaseQuery({ baseUrl: "https://api.myshop.com/" }),
  endpoints: (builder) => ({
    getProducts: builder.query<Product[], void>({
      query: () => "products",
    }),
    getProductBySlug: builder.query<Product, string>({
      query: (slug) => `products/${slug}`,
    }),
  }),
});

export const { useGetProductsQuery, useGetProductBySlugQuery } = apiSlice;
```

### 7.2 Using the Hook

```tsx
// src/pages/index.tsx
import { useGetProductsQuery } from "../store/apiSlice";
import { ProductCard } from "../components/product/ProductCard";
import { SimpleGrid, Spinner } from "@chakra-ui/react";

export default function Home() {
  const { data: products, error, isLoading } = useGetProductsQuery();

  if (isLoading) return <Spinner />;
  if (error) return <p>Error loading products.</p>;

  return (
    <SimpleGrid columns={[1, 2, 3]} spacing={4} p={4}>
      {products?.map(p => <ProductCard key={p.id} product={p} />)}
    </SimpleGrid>
  );
}
```

