## 8. Authentication & Authorization

1. **Auth flow** – JWT + refresh tokens.  
2. **Next.js API route** – `/api/auth/login` that returns a token.  
3. **Secure cookie** – `httpOnly`, `SameSite=Lax`.  
4. **Protected pages** – `getServerSideProps` checks token.  
5. **Admin role** – store `role` in JWT payload; guard admin routes.

```ts
// src/hooks/useAuth.ts
import { useEffect, useState } from "react";
import { useRouter } from "next/router";

export const useAuth = () => {
  const [user, setUser] = useState(null);
  const router = useRouter();

  useEffect(() => {
    const token = localStorage.getItem("token");
    if (!token) {
      router.push("/login");
      return;
    }
    // decode token or fetch user profile
    setUser({ id: "123", role: "admin" });
  }, []);

  return { user };
};
```

---

## 9. Checkout Flow

1. **Cart summary** → `POST /api/checkout`  
2. **Payment** – Stripe Elements or PayPal SDK.  
3. **Order confirmation** – email via SendGrid / SES.  
4. **Post‑payment webhook** – update order status.

```tsx
// src/pages/checkout.tsx
import { useSelector } from "react-redux";
import { RootState } from "../store/store";
import { Button, Box, Text } from "@chakra-ui/react";

export default function Checkout() {
  const items = useSelector((state: RootState) => state.cart.items);
  const total = items.reduce((sum, i) => sum + i.price * i.qty, 0);

  const handleCheckout = async () => {
    const res = await fetch("/api/checkout", {
      method: "POST",
      body: JSON.stringify({ items }),
    });
    const { clientSecret } = await res.json();
    // redirect to Stripe Elements or open modal
  };

  return (
    <Box p={4}>
      <Text fontSize="2xl">Checkout</Text>
      {/* Render items */}
      <Button mt={4} colorScheme="teal" onClick={handleCheckout}>
        Pay ${total.toFixed(2)}
      </Button>
    </Box>
  );
}
```

