## 10. Testing Strategy

| Type | Tool | Example |
|------|------|---------|
| Unit | Jest + React Testing Library | Test `ProductCard` renders title & price |
| Integration | React Testing Library + MSW | Mock API responses for `useGetProductsQuery` |
| End‑to‑End | Cypress | Simulate adding to cart, checkout, and verify order confirmation |

```tsx
// __tests__/ProductCard.test.tsx
import { render, screen } from "@testing-library/react";
import { ProductCard } from "../src/components/product/ProductCard";
import { ChakraProvider } from "@chakra-ui/react";

test("renders product title and price", () => {
  const product = { id: "1", title: "Test", price: 9.99, imageUrl: "" };
  render(
    <ChakraProvider>
      <ProductCard product={product} />
    </ChakraProvider>
  );
  expect(screen.getByText("Test")).toBeInTheDocument();
  expect(screen.getByText("$9.99")).toBeInTheDocument();
});
```

